{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
`);
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
}
const projectSelect = `
  SELECT projects.id, projects.name, projects.archived, projects.default_task_priority,
    COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
`;
const listProjects = database.prepare(`${projectSelect} GROUP BY projects.id ORDER BY projects.id`);
const getProject = database.prepare(`${projectSelect} WHERE projects.id = ? GROUP BY projects.id`);
const updateProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateProjectDefault = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, project_id, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id');
const getTask = database.prepare('SELECT id, project_id, title, completed, priority FROM tasks WHERE project_id = ? AND id = ?');
const createTask = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function sendJson(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

function taskJson(task) {
  return { ...task, completed: Boolean(task.completed) };
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return sendJson(response, 200, { status: 'ok' });
    }
    if (request.method === 'GET' && path === '/api/projects') {
      return sendJson(response, 200, listProjects.all());
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return sendJson(response, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readJson(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return sendJson(response, 201, getProject.get(result.lastInsertRowid));
    }
    if (request.method === 'PATCH' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      if (!project) return sendJson(response, 404, { error: 'Project not found' });
      const input = await readJson(request);
      if (Object.hasOwn(input || {}, 'default_task_priority')) {
        if (project.archived) return sendJson(response, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_task_priority)) {
          return sendJson(response, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        updateProjectDefault.run(input.default_task_priority, project.id);
        return sendJson(response, 200, getProject.get(project.id));
      }
      if (Object.hasOwn(input || {}, 'name')) {
        if (project.archived) return sendJson(response, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return sendJson(response, 400, { error: 'Project name is required' });
        renameProject.run(name, project.id);
        return sendJson(response, 200, getProject.get(project.id));
      }
      if (typeof input?.archived !== 'boolean') {
        return sendJson(response, 400, { error: 'Archive state must be a boolean' });
      }
      updateProject.run(Number(input.archived), projectMatch[1]);
      return sendJson(response, 200, getProject.get(projectMatch[1]));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = getProject.get(projectId);
      if (!project) return sendJson(response, 404, { error: 'Project not found' });
      if (!taskId && request.method === 'GET') {
        return sendJson(response, 200, listTasks.all(projectId).map(taskJson));
      }
      if (!taskId && request.method === 'POST') {
        if (project.archived) return sendJson(response, 409, { error: 'Archived project' });
        const input = await readJson(request);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return sendJson(response, 400, { error: 'Task title is required' });
        const result = createTask.run(projectId, title, project.default_task_priority);
        return sendJson(response, 201, taskJson(getTask.get(projectId, result.lastInsertRowid)));
      }
      if (taskId && request.method === 'PATCH') {
        if (!getTask.get(projectId, taskId)) return sendJson(response, 404, { error: 'Task not found' });
        if (project.archived) return sendJson(response, 409, { error: 'Archived project' });
        const input = await readJson(request);
        if (Object.hasOwn(input || {}, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return sendJson(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          updateTaskPriority.run(input.priority, projectId, taskId);
          return sendJson(response, 200, taskJson(getTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return sendJson(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return sendJson(response, 200, taskJson(getTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') {
          return sendJson(response, 400, { error: 'Completion must be a boolean' });
        }
        updateTask.run(Number(input.completed), projectId, taskId);
        return sendJson(response, 200, taskJson(getTask.get(projectId, taskId)));
      }
    }
    const asset = assets.get(path) || (/^\/projects\/\d+$/.test(path) ? assets.get('/') : null);
    if (request.method === 'GET' && asset) {
      response.writeHead(200, { 'Content-Type': asset[0] });
      return response.end(asset[1]);
    }
    sendJson(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return sendJson(response, error.status, { error: error.message });
    console.error(error);
    sendJson(response, 500, { error: 'Unable to complete request' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    database.close();
    process.exit(0);
  }));
}
const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p');
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
}

function projectRow(project, drawProjects) {
  const row = element('li');
  row.dataset.testid = 'project-row';
  const open = element('button', 'Open project');
  open.type = 'button';
  open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const summary = element('span', `${project.completed_count}/${project.total_count} completed`);
  summary.dataset.testid = 'project-summary';
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
  archive.type = 'button';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      drawProjects();
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(element('span', project.name), summary, open, archive);
  return row;
}

async function renderTasks(project) {
  const endpoint = `/api/projects/${project.id}/tasks`;
  const defaultLabel = element('label', 'Default task priority');
  defaultLabel.htmlFor = 'default-task-priority';
  const defaultPriority = element('select');
  defaultPriority.id = defaultLabel.htmlFor;
  for (const value of ['Low', 'Normal', 'High']) {
    const option = element('option', value);
    option.value = value;
    defaultPriority.append(option);
  }
  defaultPriority.value = project.default_task_priority;
  defaultPriority.disabled = Boolean(project.archived);
  defaultPriority.addEventListener('change', async () => {
    if (project.archived) return;
    defaultPriority.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ default_task_priority: defaultPriority.value }),
      });
      project.default_task_priority = saved.default_task_priority;
      defaultPriority.value = project.default_task_priority;
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) {
      defaultPriority.value = project.default_task_priority;
      showError(error.message);
    } finally {
      defaultPriority.disabled = Boolean(project.archived);
    }
  });
  const defaultControls = element('div');
  defaultControls.className = 'task-filter';
  defaultControls.append(defaultLabel, defaultPriority);
  const form = element('form');
  const titleLabel = element('label', 'Task title');
  titleLabel.htmlFor = 'task-title';
  const titleInput = element('input');
  titleInput.id = 'task-title';
  titleInput.name = 'title';
  titleInput.type = 'text';
  const submit = element('button', 'Create task');
  submit.type = 'submit';
  submit.disabled = true;
  form.append(titleLabel, titleInput, submit);

  const filterLabel = element('label', 'Task filter');
  filterLabel.htmlFor = 'task-filter';
  const filter = element('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = element('option', value);
    option.value = value;
    filter.append(option);
  }
  filter.value = 'All';
  const filterControls = element('div');
  filterControls.className = 'task-filter';
  filterControls.append(filterLabel, filter);
  const priorityFilterLabel = element('label', 'Priority filter');
  priorityFilterLabel.htmlFor = 'priority-filter';
  const priorityFilter = element('select');
  priorityFilter.id = 'priority-filter';
  for (const value of ['All', 'Low', 'Normal', 'High']) {
    const option = element('option', value);
    option.value = value;
    priorityFilter.append(option);
  }
  priorityFilter.value = 'All';
  const priorityFilterControls = element('div');
  priorityFilterControls.className = 'task-filter';
  priorityFilterControls.append(priorityFilterLabel, priorityFilter);
  const list = element('ul');
  list.setAttribute('aria-label', 'Tasks');
  app.append(form, defaultControls, filterControls, priorityFilterControls, list);
  const tasks = await request(endpoint);

  function matchesFilter(task) {
    const matchesCompletion = filter.value === 'All' || (filter.value === 'Completed' ? task.completed : !task.completed);
    const matchesPriority = priorityFilter.value === 'All' || task.priority === priorityFilter.value;
    return matchesCompletion && matchesPriority;
  }

  function taskRow(task) {
    const row = element('li');
    row.dataset.testid = 'task-row';
    const checkbox = element('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = Boolean(project.archived);
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      if (project.archived) return;
      checkbox.disabled = true;
      try {
        const saved = await request(`${endpoint}/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        task.completed = saved.completed;
        drawTasks();
        app.querySelector('[role="alert"]')?.remove();
      } catch (error) {
        checkbox.checked = task.completed;
        showError(error.message);
      } finally {
        checkbox.disabled = Boolean(project.archived);
      }
    });
    const renameForm = element('form');
    const renameLabel = element('label', 'New task title');
    renameLabel.htmlFor = `new-task-title-${task.id}`;
    const renameInput = element('input');
    renameInput.id = renameLabel.htmlFor;
    renameInput.name = 'title';
    renameInput.type = 'text';
    renameInput.disabled = Boolean(project.archived);
    const renameButton = element('button', 'Rename task');
    renameButton.type = 'submit';
    renameButton.disabled = Boolean(project.archived);
    renameForm.append(renameLabel, renameInput, renameButton);
    renameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (project.archived) return;
      const title = renameInput.value.trim();
      if (!title) return showError('Task title is required');
      renameButton.disabled = true;
      try {
        const saved = await request(`${endpoint}/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        task.title = saved.title;
        drawTasks();
        app.querySelector('[role="alert"]')?.remove();
      } catch (error) {
        showError(error.message);
      } finally {
        renameButton.disabled = Boolean(project.archived);
      }
    });
    const priorityLabel = element('label', 'Task priority');
    priorityLabel.htmlFor = `task-priority-${task.id}`;
    const priority = element('select');
    priority.id = priorityLabel.htmlFor;
    for (const value of ['Low', 'Normal', 'High']) {
      const option = element('option', value);
      option.value = value;
      priority.append(option);
    }
    priority.value = task.priority;
    priority.disabled = Boolean(project.archived);
    priority.addEventListener('change', async () => {
      if (project.archived) return;
      priority.disabled = true;
      try {
        const saved = await request(`${endpoint}/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ priority: priority.value }),
        });
        task.priority = saved.priority;
        drawTasks();
        app.querySelector('[role="alert"]')?.remove();
      } catch (error) {
        priority.value = task.priority;
        showError(error.message);
      } finally {
        priority.disabled = Boolean(project.archived);
      }
    });
    const priorityControls = element('div');
    priorityControls.className = 'task-priority';
    priorityControls.append(priorityLabel, priority);
    row.append(element('span', task.title), checkbox, renameForm, priorityControls);
    return row;
  }

  function drawTasks() {
    list.replaceChildren(...tasks.filter(matchesFilter).map(taskRow));
  }

  drawTasks();
  filter.addEventListener('change', drawTasks);
  priorityFilter.addEventListener('change', drawTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    const title = titleInput.value.trim();
    if (!title) return showError('Task title is required');
    submit.disabled = true;
    try {
      const task = await request(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      drawTasks();
      titleInput.value = '';
      app.querySelector('[role="alert"]')?.remove();
      titleInput.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = Boolean(project.archived);
    }
  });
  submit.disabled = Boolean(project.archived);
}

function renderRename(project, heading) {
  const form = element('form');
  const label = element('label', 'New project name');
  label.htmlFor = 'new-project-name';
  const input = element('input');
  input.id = 'new-project-name';
  input.name = 'name';
  input.type = 'text';
  input.disabled = Boolean(project.archived);
  const submit = element('button', 'Rename project');
  submit.type = 'submit';
  submit.disabled = Boolean(project.archived);
  form.append(label, input, submit);
  app.append(form);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    const name = input.value.trim();
    if (!name) return showError('Project name is required');
    submit.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      Object.assign(project, saved);
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = Boolean(project.archived);
    }
  });
}

async function render() {
  const match = window.location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    const back = element('button', 'Projects');
    back.addEventListener('click', () => { window.location.href = '/'; });
    app.append(back);
    const project = await request(`/api/projects/${match[1]}`);
    const heading = element('h1', project.name);
    app.append(heading);
    document.title = `${project.name} · Workboard`;
    if (project.archived) app.append(element('p', 'Archived project'));
    await renderTasks(project);
    renderRename(project, heading);
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const submit = element('button', 'Create project');
  submit.type = 'submit';
  submit.disabled = true;
  const list = element('ul');
  list.setAttribute('aria-label', 'Projects');
  form.append(label, input, submit);
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const value of ['Active', 'Archived']) {
    const option = element('option', value);
    option.value = value;
    filter.append(option);
  }
  filter.value = 'Active';
  const filterControls = element('div');
  filterControls.className = 'project-filter';
  filterControls.append(filterLabel, filter);
  app.append(form, filterControls, list);
  const projects = await request('/api/projects');
  function drawProjects() {
    list.replaceChildren(...projects
      .filter((project) => Boolean(project.archived) === (filter.value === 'Archived'))
      .map((project) => projectRow(project, drawProjects)));
  }
  drawProjects();
  filter.addEventListener('change', drawProjects);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) return showError('Project name is required');
    submit.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      projects.push(project);
      drawProjects();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = false;
    }
  });
  submit.disabled = false;
}

render().catch((error) => showError(error.message)).finally(() => {
  app.setAttribute('aria-busy', 'false');
});

